python3 -c "
import re, json
html = open('/tmp/repo.html').read()
matches = re.findall(r'<script type=\"application/json\"[^>]*>(.*?)</script>', html, re.S)
for i, block in enumerate(matches):
    try:
        j = json.loads(block)
    except json.JSONDecodeError:
        print(i, 'JSON decode error')
        continue
    if isinstance(j, dict):
        keys = list(j.keys())[:10]
        print(i, keys, '...', len(block))
    else:
        print(i, type(j).__name__, len(block))
"

